def solve():
    import sys

    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    index = 1

    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1

        if n == 0:
            results.append(-1)
            continue

        arr = list(map(int, data[index:index + n]))
        index += n

        if n == 1:
            results.append(-1)
            continue

        # Find inversion pairs (where arr[i] > arr[i+1])
        inversions = []
        for i in range(n - 1):
            if arr[i] > arr[i + 1]:
                inversions.append(i)

        if len(inversions) == 0:
            # Already sorted
            results.append(-1)
        elif len(inversions) > 1:
            # More than one segment needs fixing
            results.append(-1)
        else:
            # Exactly one inversion at position i
            i = inversions[0]

            # Try changing arr[i] or arr[i+1]
            # Check if changing arr[i] makes it sorted
            can_fix_by_changing_i = False
            can_fix_by_changing_i_plus_1 = False

            # Option 1: Change arr[i] to fix the inversion
            if i == 0 or (i > 0 and arr[i - 1] <= arr[i + 1]):
                can_fix_by_changing_i = True

            # Option 2: Change arr[i+1] to fix the inversion
            if i + 1 == n - 1 or (i + 2 < n and arr[i] <= arr[i + 2]):
                can_fix_by_changing_i_plus_1 = True

            if can_fix_by_changing_i and not can_fix_by_changing_i_plus_1:
                results.append(i)
            elif can_fix_by_changing_i_plus_1 and not can_fix_by_changing_i:
                results.append(i + 1)
            elif can_fix_by_changing_i and can_fix_by_changing_i_plus_1:
                # Prefer changing the earlier element
                if i == 0:
                    results.append(i)
                else:
                    # Both work, choose the one that makes sorted order
                    # We need to check which gives correct order
                    results.append(i)
            else:
                results.append(-1)

    for result in results:
        print(result)

solve()
